(function (window) {
    'use strict';

    var Monetix = window.Monetix || (window.Monetix = {});

    /**
     * Binds AJAX enhancement to index tables marked with [data-ajax-table].
     * The surrounding container holds a <form data-ajax-filter> whose GET fields
     * drive the query, plus pagination links generated by Laravel.
     *
     * Search inputs are debounced (~350ms), selects/checkboxes fire immediately.
     * Pagination links are intercepted and loaded without a full page reload.
     * Works purely as an enhancement: without JS the normal GET form still works.
     */
    function bindAjaxTables() {
        document.querySelectorAll('[data-ajax-table]').forEach(function (container) {
            if (container.getAttribute('data-ajax-bound') === '1') { return; }
            container.setAttribute('data-ajax-bound', '1');

            var form = container.querySelector('form[data-ajax-filter]');

            function buildUrl() {
                var params = new URLSearchParams();
                if (form) {
                    new FormData(form).forEach(function (value, key) {
                        // Guard: FormData should never contain "[object HTMLInputElement]"
                        if (typeof value === 'string' && value.indexOf('[object') !== -1) {
                            console.error('[Monetix] Blocked bad FormData value for key', key, value);
                            return;
                        }
                        if (value !== '' && value !== null) { params.append(key, value); }
                    });
                }
                var qs = params.toString();
                // Extra guard: if pathname itself was corrupted
                var path = window.location.pathname;
                if (path.indexOf('[object') !== -1 || path.indexOf('%5Bobject') !== -1) {
                    console.error('[Monetix] Corrupted pathname detected', path);
                    path = path.replace(/\/\[object[^\/?]*/g, '').replace(/%5Bobject[^\/]*/gi, '');
                    if (!path) path = '/';
                }
                return qs ? (path + '?' + qs) : path;
            }

            function load() {
                var url = buildUrl();
                if (url.indexOf('[object') !== -1 || url.indexOf('%5Bobject') !== -1) {
                    console.error('[Monetix] Blocked load with stringified object', url);
                    if (window.Monetix && Monetix.toast) Monetix.toast('Invalid filter value — please refresh.', 'danger');
                    return;
                }
                Monetix.loadPage(url, { preserveFocus: true });
            }

            if (form) {
                form.querySelectorAll('input[type="text"], input[type="search"], input:not([type])').forEach(function (input) {
                    if (input.hasAttribute('data-ajax-ignore')) { return; }
                    input.addEventListener('input', Monetix.debounce(load, 350));
                });
                form.querySelectorAll('select, input[type="checkbox"], input[type="radio"], input[type="date"], input[type="number"]').forEach(function (field) {
                    if (field.hasAttribute('data-ajax-ignore')) { return; }
                    field.addEventListener('change', load);
                });
                form.addEventListener('submit', function (e) { e.preventDefault(); load(); });
            }

            // Custom widgets (e.g. a searchable dropdown backed by a hidden
            // input) can trigger a reload by dispatching change on [data-ajax-reload].
            container.querySelectorAll('[data-ajax-reload]').forEach(function (el) {
                el.addEventListener('change', load);
            });

            // AJAX pagination (links rendered by Laravel's paginator).
            container.querySelectorAll('[data-ajax-pagination] a[href]').forEach(function (link) {
                link.addEventListener('click', function (e) {
                    if (link.hasAttribute('data-ajax-ignore')) { return; }
                    var url = link.getAttribute('href');
                    if (!url) { return; }
                    if (url.indexOf('[object') !== -1 || url.indexOf('%5Bobject') !== -1) {
                        console.error('[Monetix] Blocked pagination with bad URL', url);
                        e.preventDefault();
                        return;
                    }
                    e.preventDefault();
                    if (Monetix.navHistory) { Monetix.navHistory.record(url); }
                    Monetix.loadPage(url, { preserveFocus: false });
                });
            });
        });
    }

    Monetix.bindAjaxTables = bindAjaxTables;

    if (document.readyState === 'loading') {
        document.addEventListener('DOMContentLoaded', bindAjaxTables);
    } else {
        bindAjaxTables();
    }

})(window);